let entries=[];let revs={};
const $=id=>document.getElementById(id);
function fmt(n){return String(Math.round(n*100)/100);}
function say(t,err){const m=$('msg');m.textContent=t;m.className=err?'error':'';}
function render(){
  let total=0;for(const e of entries){total+=e.value;}
  $('total').textContent=fmt(total);
  const list=$('list');list.textContent='';
  for(const e of entries){
    const li=document.createElement('li');
    const s=document.createElement('span');s.textContent=e.name+': '+fmt(e.value);
    const b=document.createElement('button');b.type='button';b.textContent='Remove';
    b.setAttribute('aria-label','Remove '+e.name);
    b.addEventListener('click',()=>removeEntry(e.id));
    li.appendChild(s);li.appendChild(b);list.appendChild(li);
  }
  const has=entries.length>0;
  $('empty').hidden=has;$('chart').hidden=!has;
  if(has){
    tessera.chart($('chart'),{type:'pie',title:'Spending this month',labels:entries.map(e=>e.name.slice(0,80)),series:[{name:'Spending',values:entries.map(e=>e.value)}]});
  }
}
async function load(){
  const r=await tessera.call('data.read',{});
  entries=Array.isArray(r.data.entries)?r.data.entries:[];
  revs=(r.revisions&&r.revisions.entries)||{};
  render();
}
async function addEntry(){
  const name=$('name').value.trim();
  const raw=$('value').value;
  const value=Number(raw);
  if(!name){say('Type a name for the item.',true);$('name').focus();return;}
  if(raw===''||!isFinite(value)||value<0){say('Type an amount of 0 or more.',true);$('value').focus();return;}
  try{
    await tessera.call('data.patch',{operations:[{op:'add',collection:'entries',record:{name:name,value:value}}]});
    $('name').value='';$('value').value='';
    await load();
    say('Added '+name+'.');
    $('name').focus();
  }catch(e){say('Could not save the item. Your entry is still here; try again.',true);}
}
async function removeEntry(id){
  const rc=revs[id];
  const e=entries.find(x=>x.id===id);
  try{
    await tessera.call('data.patch',{operations:[{op:'remove',collection:'entries',id:id,revisionCount:rc}]});
    await load();
    say('Removed '+(e?e.name:'item')+'.');
    $('name').focus();
  }catch(err){say('Could not remove the item. Try again.',true);}
}
$('add').addEventListener('click',addEntry);
$('value').addEventListener('keydown',ev=>{if(ev.key==='Enter'){addEntry();}});
$('name').addEventListener('keydown',ev=>{if(ev.key==='Enter'){addEntry();}});
load().catch(()=>say('Could not load your spending.',true));

